const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat /Users/ab/.agents/skills/syncer/SKILL.md",max_output_tokens:14000}),
  tools.exec_command({cmd:"pwd && rg --files -g AGENTS.md -g '*sync*' -g 'composer.json' -g '*phpstan*' -g '*phpunit*' -g '*guard*' -g '.gitignore' -g '*neon*' -g '*.dist' -g '.editorconfig' -g '.php-cs-fixer*' -g 'Makefile' -g 'mise.toml' -g 'justfile' -g 'README*' -g '*.xml' -g '*.json' -g '*.hcl' -g '*.md' | head -n 160",max_output_tokens:6000}),
  tools.exec_command({cmd:"git status --short --branch && ls -la /Users/ab/Projects",max_output_tokens:6000})
]); results.forEach((r,i)=>text({i,...r}));

