 tools.exec_command({cmd:"syncer apply --help && syncer add --help && syncer validate --help && cat /Users/ab/Projects/syncer-rs/examples/local.hcl",max_output_tokens:7000}),
 tools.exec_command({cmd:"rg --files -uu projects -g composer.json -g AGENTS.md -g phpstan.neon -g '*phpunit*.xml*' -g .php-cs-fixer.dist.php -g 'loc.yaml' -g 'tree.yaml' -g 'deptrac.yaml' -g .git -g '!**/vendor/**' -g '!**/node_modules/**' -g '!**/.git/**' -g '!**/build/**' | head -n 160 && cat .php-cs-fixer.dist.php phpcs.xml.dist loc.yaml tree.yaml",max_output_tokens:12000})
]);for(let i=0;i<results.length;i++)text({i,...results[i]});

