#!/usr/bin/env python3
"""Run Syncer checks only; all state and reports stay inside ignored sync/."""

import argparse
from collections import Counter
from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path
import shutil
import subprocess
import sys

HERE = Path(__file__).resolve().parent


def run(base, *args):
    return subprocess.run([*base, *args], text=True, capture_output=True)


def checked(base, *args):
    result = run(base, *args)
    if result.returncode:
        raise RuntimeError(result.stderr.strip() or result.stdout.strip())
    return json.loads(result.stdout)


def fingerprint(path):
    if not path.exists():
        return None
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("projects", nargs="*", help="Optional names from projects/; default: all four")
    parser.add_argument("--diff", action="store_true", help="Include proposed configuration diffs in JSON reports")
    args = parser.parse_args()
    manifests = json.loads((HERE / "manifest.json").read_text())
    names = {m["project"] for m in manifests}
    if set(args.projects) - names:
        parser.error("Unknown projects: " + ", ".join(sorted(set(args.projects) - names)))
    executable = shutil.which("syncer")
    if executable is None:
        parser.error("syncer is not on PATH")
    reports = HERE / "reports"
    reports.mkdir(exist_ok=True)
    summary = []
    for manifest in manifests:
        name = manifest["project"]
        if args.projects and name not in args.projects:
            continue
        root = (HERE.parent / "projects" / name).resolve(strict=True)
        if str(root) != manifest["root"]:
            raise RuntimeError(f"{name} changed location; run python3 sync/generate.py first")
        state = HERE / "state" / name
        state.mkdir(parents=True, exist_ok=True)
        base = [executable, "--dev-extensions", "--project", str(root),
                "--state-dir", str(state), "--output", "json"]
        paths = {rule["target"]: root / rule["target"] for rule in manifest["rules"]}
        before = {target: fingerprint(path) for target, path in paths.items()}
        entry = {"project": name, "scopes": len({r["scope"] for r in manifest["rules"]}),
                 "rules": len(manifest["rules"]), "root": str(root)}
        try:
            extensions = checked(base, "extension", "list")
            kinds = {kind for extension in extensions for kind in extension.get("kinds", [])}
            needed = {r["kind"] for r in manifest["rules"]} - {"regex", "text", "file"}
            if needed - kinds:
                raise RuntimeError("Missing Syncer extensions for " + ", ".join(sorted(needed - kinds)))
            checked(base, "validate", str(HERE / manifest["policy"]))
            sources = checked(base, "list")
            # The private state directory belongs to this checker, never to a daemon.
            if any(source["name"] != "toolkit" for source in sources):
                raise RuntimeError(f"Unexpected source in isolated state {state}; review before checking")
            if sources:
                checked(base, "remove", "toolkit")
            checked(base, "add", "toolkit", str(HERE / manifest["policy"]), "--allow-root", str(root))
            result = run(base, "apply", "--check", *(["--diff"] if args.diff else []))
            entry["exit_code"] = result.returncode
            (reports / f"{name}.stderr.txt").write_text(result.stderr)
            if result.returncode not in (0, 2, 3):
                raise RuntimeError(result.stderr.strip() or result.stdout.strip())
            plan = json.loads(result.stdout)
            (reports / f"{name}.json").write_text(json.dumps(plan, indent=2, ensure_ascii=False) + "\n")
            entry["plan"] = plan
        except (RuntimeError, ValueError) as error:
            entry.update(exit_code=1, error=str(error))
        after = {target: fingerprint(path) for target, path in paths.items()}
        entry["targets_unchanged"] = before == after
        if before != after:
            entry.update(exit_code=1, error="Target content changed during checking; inspect concurrent edits")
        entry["target_hashes"] = after
        summary.append(entry)
        print(f"{name}: exit={entry['exit_code']}, rules={entry['rules']}, targets_unchanged={entry['targets_unchanged']}")
        if entry.get("error"):
            print(entry["error"], file=sys.stderr)

    report = {"checked_at": datetime.now(timezone.utc).isoformat(), "projects": summary}
    (reports / "summary.json").write_text(json.dumps(report, indent=2, ensure_ascii=False) + "\n")
    lines = ["# Syncer 設定監査", "", f"検査日時: {report['checked_at']}", "",
             "`syncer apply --check` のみ実行。以下の件数は適用前の違反ルール数。", ""]
    for entry in summary:
        manifest = next(m for m in manifests if m["project"] == entry["project"])
        by_id = {r["id"]: r for r in manifest["rules"]}
        lines.extend([f"## {entry['project']}", "",
                      f"終了コード: {entry['exit_code']} / 対象ファイルの内容変更なし: {entry['targets_unchanged']}", ""])
        if entry.get("error"):
            lines.extend(["検査エラー: " + entry["error"], ""])
            continue
        rules = entry["plan"].get("rules", [])
        violations = [r for r in rules if r.get("before") is False]
        lines.extend([f"{len(rules)} ルール中 {len(violations)} 件の違反。", "",
                      "| ファイル | 違反数 |", "| --- | ---: |"])
        counts = Counter(by_id[r["rule"]]["target"] for r in violations)
        lines.extend(f"| `{path}` | {count} |" for path, count in sorted(counts.items()))
        lines.extend(["", "### 違反と修正方法", ""])
        for rule in violations:
            metadata = by_id[rule["rule"]]
            state = "同期候補あり" if rule.get("after") else "手動修正が必要"
            lines.append(f"- `{metadata['target']}` / `{rule['rule']}` ({state}): {metadata['rationale']}")
        lines.append("")
    (reports / "summary.md").write_text("\n".join(lines))
    codes = {entry["exit_code"] for entry in summary}
    return next((code for code in (1, 3, 2) if code in codes), 0)


